import{_ as o,o as d,c as a,a2 as n}from"./chunks/framework.CNDaxUod.js";const g=JSON.parse('{"title":"EdgeOne Pages 部署","description":"","frontmatter":{},"headers":[],"relativePath":"zh/operations/edgeone-pages.md","filePath":"zh/operations/edgeone-pages.md","lastUpdated":1788938813000}'),c={name:"zh/operations/edgeone-pages.md"};function r(s,e,t,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="edgeone-pages-部署" tabindex="-1">EdgeOne Pages 部署 <a class="header-anchor" href="#edgeone-pages-部署" aria-label="Permalink to &quot;EdgeOne Pages 部署&quot;">​</a></h1><p>项目 <code>yunyoujun-web-resume</code> 关联本仓库 <code>main</code> 分支，仓库根目录的 <code>edgeone.json</code> 固定 Node 24.18.0、pnpm 11.25.0、安装命令和构建产物目录 <code>dist</code>。构建同时包含 Web 应用与 <code>/docs/</code> 文档。</p><p>此前控制台使用 Node 22.11.0；pnpm 11 要求至少 Node 22.13，导致安装阶段失败，线上继续保留旧部署。仅刷新 CDN 缓存无法修复构建失败。</p><h2 id="域名与登录" tabindex="-1">域名与登录 <a class="header-anchor" href="#域名与登录" aria-label="Permalink to &quot;域名与登录&quot;">​</a></h2><ul><li><code>web-resume.yunyoujun.cn</code>：直接访问 EdgeOne Pages。</li><li><code>resume.yunle.fun</code>：Cloudflare Worker <code>web-resume</code> 将页面和文档转发到上述 EdgeOne 域名，两个入口使用同一份构建产物。</li><li>主域 <code>/api/*</code> 仍由 Worker 处理，再访问 Drive API。登录开启，云简历存储关闭；页面代理不会携带 Cookie 或 Authorization。</li><li>构建开启登录界面，但前端仍检查访问域名，镜像域名不会启用账号功能。浏览器本地简历按域名隔离，不会随部署自动同步。</li></ul><p>这是页面源站迁移，主域 DNS 和登录网关仍在 Cloudflare。若后续要完全移除 Cloudflare，需要先迁移并验证同源 API、会话 Cookie、CSRF 和 SSO 回调，再切换 DNS。</p><h2 id="发布验证与回滚" tabindex="-1">发布验证与回滚 <a class="header-anchor" href="#发布验证与回滚" aria-label="Permalink to &quot;发布验证与回滚&quot;">​</a></h2><p>合并前运行完整构建、类型检查及代理测试；若项目启用了预览分支，也应验证 EdgeOne 预览部署。当前项目只自动部署 <code>main</code>，合并后必须确认生产部署成功且对应最新提交，再发布 <code>workers/wrangler.toml</code>。检查两个域名的首页资源版本、<code>/settings</code>、<code>/docs/</code>，以及主域 <code>/api/session</code> 返回 JSON、<code>/api/documents</code> 保持关闭。</p><p>EdgeOne 可切回之前成功的部署。若页面源站不可用，也可将 Worker 的 <code>ASSET_ORIGIN</code> 恢复为 <code>https://resume.elpsy.cn</code> 并重新发布；不要变更 API 开关或删除用户数据。</p>',9)])])}const m=o(c,[["render",r]]);export{g as __pageData,m as default};
